const item = $input.first().json;
const body = item.body || item;
const courseQuery = (body.courseQuery || '').toString().trim();
const examType = body.examType === 'final' ? 'final' : 'vize';
if (courseQuery.length < 2) {
  return [{ json: { invalid: true, courseQuery, examType, error: { success: false, error: { code: 'INVALID_INPUT', stage: 'input_validation', message: 'Ders adı/kodu geçersiz (en az 2 karakter).' } } } }];
}
const examTr = examType === 'final' ? 'FİNAL (dönemin tamamı)' : 'VİZE (dönemin ilk yarısı)';
const prompt = 'Manisa Celal Bayar Üniversitesi öğrencisi için sınav hazırlık asistanısın. Ders: "' + courseQuery + '". Sınav: ' + examTr + '. Bu dersin tipik müfredatını (syllabus) dikkate alarak bu sınavda çıkması beklenen ana konuları belirle. SADECE şu JSON şemasıyla yanıt ver: {"course":{"code":"","name":""},"topics":[{"title":"","description":"","importance":"yüksek|orta|düşük","videos":[{"title":"","channel":"","searchQuery":""}]}]}. Her konu için 1-3 adet YouTube eğitim videosu öner; GERÇEK video kimliği UYDURMA, bunun yerine Türkçe bir YouTube arama sorgusu (searchQuery) ver. Tüm metinler Türkçe olsun.';
return [{ json: { invalid: false, courseQuery, examType, prompt } }];

const g = $input.first().json;
const ctx = $('Hazırla & Doğrula').first().json;
const examType = ctx.examType || 'vize';
const courseQuery = ctx.courseQuery || '';
function errOut(code, stage, message) {
  return [{ json: { response: { success: false, error: { code, stage, message } } } }];
}
if (g && g.error) {
  const m = (g.error && (g.error.message || g.error.reason)) || JSON.stringify(g.error);
  return errOut('OPENAI_ERROR', 'model_generation', 'OpenAI çağrısı başarısız: ' + m);
}
// OpenAI 'Message a Model' çıktısı n8n sürümüne göre farklı konumda olabilir; hepsini dene
let raw;
if (g && g.message && g.message.content !== undefined) raw = g.message.content;
else if (g && g.content !== undefined) raw = g.content;
else if (g && g.text !== undefined) raw = g.text;
else if (g && g.choices && g.choices[0] && g.choices[0].message) raw = g.choices[0].message.content;
let parsed;
try {
  if (raw === undefined || raw === null || raw === '') throw new Error('Model boş yanıt döndürdü.');
  parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (e) {
  return errOut('SCHEMA_INVALID', 'response_format', 'Model yanıtı çözümlenemedi: ' + e.message);
}
const topics = Array.isArray(parsed.topics) ? parsed.topics : [];
if (!topics.length) {
  return errOut('SYLLABUS_NOT_FOUND', 'syllabus_fetch', 'Bu ders için konu üretilemedi.');
}
const model = (g && g.model) || (g && g.message && g.message.model) || 'openai';
const response = { success: true, source: 'n8n', course: parsed.course || { code: '', name: courseQuery }, examType, topics, meta: { model, generatedAt: new Date().toISOString() } };
return [{ json: { response } }];
